import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';
import { Container, Row, Col, Card, Form, Button, Alert, ProgressBar } from 'react-bootstrap';

const Makepayment = () => {
  const navigate = useNavigate();
  const location = useLocation();
  
  // Get cart data from navigation state and ensure totalAmount is a number
  const { cartItems = [], totalAmount: totalAmountRaw = 0 } = location.state || {};
  const totalAmount = Number(totalAmountRaw);
  
  const [phone, setPhone] = useState('');
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState('');
  const [error, setError] = useState('');

  const payNow = async (e) => {
    e.preventDefault();
    if (!phone || phone.length < 10 || isNaN(phone)) {
      setError('Please enter a valid phone number (e.g., 712345678)');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const response = await axios.post('https://sengi2025.pythonanywhere.com/api/mpesa_payment', {
        amount: totalAmount,
        phone: `254${phone}`,
      });

      setSuccess(response.data.message || 'Payment initiated successfully!');
      setPhone('');

      setTimeout(() => {
        navigate('/checkout', { state: { cartItems, totalAmount } });
      }, 3000);

    } catch (err) {
      setError('Payment failed. Please try again later.');
      console.error('Payment error:', err.response?.data || err.message);
    } finally {
      setLoading(false);
    }
  };

  if (cartItems.length === 0) {
    return (
      <Container className="text-center py-5">
        <Alert variant="danger" className="shadow-sm rounded-4">
          <h2 className="fw-bold mb-3">Your Cart is Empty</h2>
          <i className="bi bi-cart-x text-danger" style={{ fontSize: '4rem' }}></i>
          <p className="mt-3 mb-4">Please add some products to your cart first</p>
          <Button 
            variant="primary" 
            onClick={() => navigate('/shop')}
            className="px-4 py-2 rounded-pill"
          >
            <i className="bi bi-arrow-left me-2"></i>Back to Shop
          </Button>
        </Alert>
      </Container>
    );
  }

  return (
    <Container className="py-5">
      <Row className="justify-content-center mb-4">
        <Col lg={8}>
          <div className="d-flex justify-content-between align-items-center">
            <div>
              <h1 className="fw-bold text-primary mb-1">Secure Payment</h1>
              <p className="text-muted">Complete your tilapia purchase with M-PESA</p>
            </div>
            <div className="text-end">
              <div className="badge bg-primary rounded-pill p-2 px-3">
                <i className="bi bi-lock-fill me-1"></i> Secure
              </div>
              <div className="text-muted small mt-1">Payment encrypted</div>
            </div>
          </div>
          
          <ProgressBar now={66} variant="primary" className="mb-5 rounded-pill" style={{ height: '8px' }} />
        </Col>
      </Row>
      
      <Row className="justify-content-center">
        <Col lg={8}>
          <Card className="border-0 shadow-lg rounded-4 overflow-hidden">
            <Card.Header className="bg-gradient-primary text-white py-3">
              <div className="d-flex justify-content-between align-items-center">
                <h2 className="mb-0 fw-bold">Complete Your Purchase</h2>
                <div className="fs-1">🐟</div>
              </div>
            </Card.Header>
            
            <Card.Body className="p-4">
              <Row>
                <Col md={6} className="mb-4 mb-md-0">
                  <Card className="border-0 shadow-sm h-100">
                    <Card.Body className="p-4">
                      <h4 className="text-primary mb-4 fw-bold d-flex align-items-center">
                        <i className="bi bi-receipt me-2"></i>Order Summary
                      </h4>
                      
                      <div className="mb-4">
                        {cartItems.map((item, index) => (
                          <div key={index} className="mb-3 border-bottom pb-3">
                            <div className="d-flex align-items-center">
                              <div className="bg-light rounded-circle p-2 me-3">
                                <i className="bi bi-fish text-primary" style={{ fontSize: '1.5rem' }}></i>
                              </div>
                              <div className="flex-grow-1">
                                <h6 className="mb-0 fw-bold">{item.name}</h6>
                                <p className="text-muted mb-0 small">
                                  {item.quantity} kg × KES {item.price.toFixed(2)}
                                </p>
                              </div>
                              <div className="fw-bold text-end">
                                KES {(item.price * item.quantity).toFixed(2)}
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                      
                      <div className="bg-light rounded-3 p-3">
                        <div className="d-flex justify-content-between mb-2">
                          <span>Subtotal:</span>
                          <span>KES {totalAmount.toFixed(2)}</span>
                        </div>
                        <div className="d-flex justify-content-between mb-2">
                          <span>Shipping:</span>
                          <span className="text-success">FREE</span>
                        </div>
                        <div className="d-flex justify-content-between fw-bold fs-5 pt-2 border-top">
                          <span>Total:</span>
                          <span className="text-success">KES {totalAmount.toFixed(2)}</span>
                        </div>
                      </div>
                    </Card.Body>
                  </Card>
                </Col>
                
                <Col md={6}>
                  <Card className="border-0 shadow-sm h-100">
                    <Card.Body className="p-4">
                      <h4 className="text-success mb-4 fw-bold d-flex align-items-center">
                        <i className="bi bi-wallet2 me-2"></i>Lipa na M-PESA
                      </h4>
                      
                      {success && (
                        <Alert variant="success" className="rounded-4">
                          <i className="bi bi-check-circle-fill me-2"></i>
                          {success}
                        </Alert>
                      )}
                      
                      {error && (
                        <Alert variant="danger" className="rounded-4">
                          <i className="bi bi-exclamation-circle-fill me-2"></i>
                          {error}
                        </Alert>
                      )}
                      
                      <Form onSubmit={payNow}>
                        <div className="mb-4 p-3 bg-light rounded-3">
                          <div className="d-flex justify-content-between align-items-center">
                            <div>
                              <span className="text-muted">Amount Due</span>
                              <h3 className="text-success fw-bold mb-0">KES {totalAmount.toFixed(2)}</h3>
                            </div>
                            <div className="fs-1">💰</div>
                          </div>
                        </div>
                        
                        <Form.Group className="mb-4">
                          <Form.Label className="fw-medium">
                            <i className="bi bi-phone me-1"></i> M-PESA Phone Number
                          </Form.Label>
                          <div className="input-group">
                            <span className="input-group-text bg-light border-end-0">
                              +254
                            </span>
                            <Form.Control 
                              type="tel"
                              placeholder="7XXXXXXXX"
                              value={phone}
                              onChange={(e) => {
                                const value = e.target.value;
                                if (/^\d*$/.test(value)) {
                                  setPhone(value.slice(0, 9));
                                }
                              }}
                              required
                              className="form-control-lg border-start-0"
                            />
                          </div>
                          <Form.Text className="text-muted">
                            Enter your Safaricom number (e.g., 712345678)
                          </Form.Text>
                        </Form.Group>
                        
                        <Button 
                          variant={loading ? "secondary" : "success"} 
                          type="submit"
                          className="w-100 py-3 rounded-pill fw-bold shadow"
                          disabled={loading}
                        >
                          {loading ? (
                            <>
                              <span className="spinner-border spinner-border-sm me-2"></span>
                              Processing Payment...
                            </>
                          ) : (
                            <>
                              <i className="bi bi-lock-fill me-2"></i>
                              Pay with M-PESA
                            </>
                          )}
                        </Button>
                      </Form>
                      
                      <div className="mt-4 pt-3 border-top text-center">
                        <div className="d-flex justify-content-center mb-3">
                          <img 
                            src="https://www.safaricom.co.ke/images/mpesa-logo.png" 
                            alt="M-Pesa" 
                            width="120"
                          />
                        </div>
                        <div className="d-flex justify-content-center gap-3 mb-3">
                          {['shield-check', 'credit-card', 'clock-history'].map((icon, i) => (
                            <div key={i} className="text-center">
                              <div className="bg-light rounded-circle p-3 mb-2">
                                <i className={`bi bi-${icon} text-primary fs-4`}></i>
                              </div>
                              <div className="small">
                                {icon === 'shield-check' && 'Secure'}
                                {icon === 'credit-card' && 'Instant'}
                                {icon === 'clock-history' && '24/7'}
                              </div>
                            </div>
                          ))}
                        </div>
                        <p className="text-muted small mb-0">
                          You'll receive a payment request on your phone
                        </p>
                      </div>
                    </Card.Body>
                  </Card>
                </Col>
              </Row>
            </Card.Body>
          </Card>
          
          <div className="mt-4 text-center">
            <p className="text-muted">
              <i className="bi bi-shield-lock me-1"></i>
              Your payment is secured with bank-level encryption
            </p>
            <div className="d-flex justify-content-center gap-2">
              {['visa', 'mastercard', 'paypal', 'apple-pay'].map((icon, i) => (
                <div key={i} className="bg-light p-2 rounded">
                  <i className={`bi bi-${icon} fs-4 text-muted`}></i>
                </div>
              ))}
            </div>
          </div>
        </Col>
      </Row>
    </Container>
  );
};

export default Makepayment;
